INSERT IGNORE INTO help_categories(code,name,sort_order,homepage_featured,status,created_at,updated_at) VALUES('construction','施工',40,0,'active',UTC_TIMESTAMP(),UTC_TIMESTAMP());
INSERT IGNORE INTO help_categories(code,name,sort_order,homepage_featured,status,created_at,updated_at) VALUES('measurement','测量',50,0,'active',UTC_TIMESTAMP(),UTC_TIMESTAMP());
